// Self-hosted videos live in public/videos/: <key>-loop.mp4 (muted preview), <key>-full.mp4 (with sound), <key>-poster.jpg.
const videoKeys = { media: 'mlm', audio: 'dad', dock: 'dock' };

// Video files for a private project id (from carrera.json), or undefined if it has no video.
export function videoFor(id) {
  const key = videoKeys[id];
  if (!key) return undefined;
  return {
    loop: `/videos/${key}-loop.mp4`,
    full: `/videos/${key}-full.mp4`,
    poster: `/videos/${key}-poster.jpg`,
  };
}
